<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/document_manager.php';require __DIR__.'/includes/quote_pdf_payload.php';require_permission('quotes.view');
$id=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT q.*,c.company_name,c.trade_name,c.tax_id,c.country,c.city,c.address,c.logo_path,c.email client_email,u.name creator_name,ou.name owner_name,d.title deal_title FROM quotations q JOIN clients c ON c.id=q.client_id LEFT JOIN users u ON u.id=q.created_by LEFT JOIN users ou ON ou.id=q.owner_user_id LEFT JOIN deals d ON d.id=q.deal_id WHERE q.id=?');$stmt->execute([$id]);$quote=$stmt->fetch();if(!$quote){http_response_code(404);exit('Cotización no encontrada.');}$stmt=db()->prepare('SELECT * FROM quotation_items WHERE quotation_id=? ORDER BY sort_order,id');$stmt->execute([$id]);$items=$stmt->fetchAll();$stmt=db()->prepare('SELECT * FROM quotation_attachments WHERE quotation_id=? ORDER BY created_at,id');$stmt->execute([$id]);$attachments=$stmt->fetchAll();$pdfPayload=quote_pdf_payload($quote,$items);$pageTitle='Cotización '.$quote['quotation_number'];require __DIR__.'/includes/header.php';?>
<style><?=quote_document_css()?></style><script src="assets/js/quote-pdf.js?v=2.0.0-local"></script>
<section class="panel"><div class="panel-header"><div><h2><?=e($quote['quotation_number'])?> · <?=e($quote['company_name'])?></h2><span class="table-sub"><?=e(language_label($quote['language']))?> · <?=e($quote['currency'])?> · Responsable: <?=e($quote['owner_name']?:'Sin asignar')?><?= $quote['deal_title']?' · Negocio: '.e($quote['deal_title']):''?></span></div><div class="actions"><a class="btn btn-light btn-small" href="quotation_print.php?id=<?=$id?>" target="_blank">Imprimir / PDF</a><button type="button" class="btn btn-secondary btn-small" data-download-quote-pdf data-filename="<?=e($quote['quotation_number'])?>.pdf">Descargar PDF</button><?php if(has_permission('quotes.send')):?><a class="btn btn-secondary btn-small" href="quotation_send.php?id=<?=$id?>">Enviar por email</a><?php endif;?><?php if(has_permission('deals.transfer')):?><a class="btn btn-light btn-small" href="quotation_assign.php?id=<?=$id?>">Transferir</a><?php endif;?><?php if(has_permission('quotes.edit')):?><a class="btn btn-primary btn-small" href="quotation_form.php?id=<?=$id?>">Editar</a><?php endif;?></div></div>
<?php if(has_permission('quotes.status')):?><div class="panel-body"><form method="post" action="quotation_status.php" class="filters"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><strong>Estado:</strong><select name="status"><?php foreach(['draft','sent','accepted','rejected','expired']as$status):?><option value="<?=$status?>" <?=$quote['status']===$status?'selected':''?>><?=e(quote_status_label($status))?></option><?php endforeach;?></select><button class="btn btn-light btn-small">Actualizar estado</button><span class="badge badge-<?=e(quote_status_class($quote['status']))?>"><?=e(quote_status_label($quote['status']))?></span></form></div><?php endif;?></section>
<script type="application/json" id="quote-pdf-data"><?=json_encode($pdfPayload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><div class="quote-preview-wrap" style="margin-top:20px" id="quote-pdf-source"><?=quote_document_html($quote,$items)?></div>
<section class="panel" style="margin-top:20px"><div class="panel-header"><div><h2>Documentos adicionales</h2><span class="table-sub">Estos archivos se adjuntan al correo junto con el PDF de la cotización.</span></div><?php if(has_permission('quotes.edit')):?><a class="btn btn-light btn-small" href="quotation_form.php?id=<?=$id?>#attachments">Agregar documento</a><?php endif;?></div><div class="panel-body attachment-list"><?php if(!$attachments):?><div class="empty">No hay documentos adicionales.</div><?php endif;?><?php foreach($attachments as$a):?><div class="attachment-item"><?=crm_icon('contract')?><div><a href="quotation_attachment_download.php?id=<?=(int)$a['id']?>"><strong><?=e($a['file_name'])?></strong></a><small><?=e($a['mime_type'])?> · <?=e(number_format(((int)$a['file_size'])/1024,1,',','.'))?> KB</small></div><?php if(has_permission('quotes.edit')):?><form method="post" action="quotation_attachment_delete.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$a['id']?>"><button class="btn btn-danger btn-small" data-confirm="¿Eliminar este documento?">Eliminar</button></form><?php endif;?></div><?php endforeach;?></div></section>
<div class="actions" style="margin-top:20px"><a class="btn btn-light" href="quotations.php">← Volver</a><?php if(has_permission('quotes.delete')):?><form method="post" action="quotation_delete.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-danger" data-confirm="¿Eliminar definitivamente esta cotización?">Eliminar cotización</button></form><?php endif;?></div>
